select id, plan, monthly_fee, lag(monthly_fee, 1) over (partition by status, customer_id order by end_date, id) as prev_monthly_fee, dense_rank() over (partition by plan order by monthly_fee nulls last) as monthly_fee_dense_rank, avg(monthly_fee) over (order by end_date, id rows between 6 preceding and 1 preceding) as monthly_fee_avg_6_prior, lead(monthly_fee, 1) over (partition by status order by monthly_fee, id) as next_monthly_fee, avg(monthly_fee) over (partition by status) as status_avg_monthly_fee from subscriptions;
